effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  float t = animate ? floor(acTime * 24.0) : 0.0;
  vec2 gp = floor(uv * acScreenSize / max(size, 0.5)) + t * 13.0;
  float n = gmHash(gp) - 0.5;
  float l = gmLum(c);
  float resp = mix(1.0, 1.0 - l, shadowBias);
  vec3 col = c + n * amount * resp * mixAmt;
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
